"""Improved harness with answer extraction, structured prompting, self-correction, and robust error handling."""

import re
import json
from harness_evolve.llm import llm_acall

SYSTEM_PROMPT = (
    "You are solving a computational reasoning puzzle. The user message contains the full task specification.\n\n"
    "Think step-by-step through the problem. Your reasoning should include:\n"
    "1. Parse the inputs and understand the code logic\n"
    "2. Simulate execution step-by-step\n"
    "3. Track state variables and transformations\n"
    "4. Verify your result\n"
    "5. Output final result\n\n"
    "Wrap your final answer in <answer> tags: <answer>your answer here</answer>\n"
    "The content inside <answer> tags must be exactly the output value in the format specified by the task.\n"
    "Do not output extra commentary after your final answer.\n"
    "Ensure numerical answers have sufficient precision."
)

ANSWER_RE = re.compile(r'<answer>(.*?)</answer>', re.DOTALL)


def extract_answer(text: str) -> str:
    """Extract content between <answer> and </answer> tags, or return cleaned text."""
    match = ANSWER_RE.search(text)
    if match:
        return match.group(1).strip()
    # Fallback: try to find anything that looks like the final answer block
    cleaned = text.strip()
    return cleaned


def looks_like_json_or_array(text: str) -> bool:
    """Heuristic check if text starts with JSON-like structures."""
    stripped = text.strip()
    if stripped.startswith('{') or stripped.startswith('['):
        try:
            json.loads(stripped)
            return True
        except (json.JSONDecodeError, ValueError):
            return False
    return False


def has_answer_tag(text: str) -> bool:
    """Check whether the text contains <answer>...</answer> tags."""
    return bool(ANSWER_RE.search(text))


async def solve(model, question, **kwargs):
    """Improved solver with structured reasoning, answer extraction, and self-correction.

    Strategy:
    1. First call: structured prompt with step-by-step reasoning guidance (temp=0.0).
    2. If response lacks answer tags or fails heuristics, retry with error feedback.
    3. Extract the answer content and return clean output wrapped in <answer> tags.
    """
    max_attempts = 2
    content = None
    last_error = None

    for attempt in range(max_attempts):
        try:
            if attempt == 0:
                messages = [
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": question},
                ]
            else:
                error_feedback = (
                    f"Your previous response did not pass verification.\n"
                    f"Please review your reasoning, fix any errors, and provide only the corrected final answer.\n"
                    f"Wrap your corrected final answer in <answer> tags: <answer>your answer here</answer>\n"
                )
                messages = [
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": question},
                    {"role": "assistant", "content": content},
                    {"role": "user", "content": error_feedback},
                ]

            content = await llm_acall(
                model=model,
                messages=messages,
                max_tokens=32768,
                temperature=0.0,
                thinking=kwargs.get("thinking"),
            )

            has_tag = has_answer_tag(content)
            looks_valid = looks_like_json_or_array(extract_answer(content))

            # Accept if it has answer tags or at least looks like a structured output
            if has_tag or looks_valid:
                extracted = extract_answer(content)
                return {
                    "answer": f"<answer>{extracted}</answer>",
                    "traces": {
                        "method": "structured_with_extraction_and_retry",
                        "attempts": attempt + 1,
                        "raw_response": content,
                        "extracted_answer": extracted,
                        "has_answer_tag": has_tag,
                    },
                }

        except Exception as e:
            last_error = str(e)
            # Gracefully handle model 404 errors
            if "NotFoundError" in str(e) or "404" in str(e):
                if content:
                    extracted = extract_answer(content)
                    return {
                        "answer": f"<answer>{extracted}</answer>",
                        "traces": {
                            "method": "structured_with_extraction_and_retry",
                            "attempts": attempt + 1,
                            "error": str(e),
                            "raw_response": content,
                            "extracted_answer": extracted,
                        },
                    }
                return {
                    "answer": "<answer></answer>",
                    "traces": {
                        "method": "structured_with_extraction_and_retry",
                        "attempts": attempt + 1,
                        "error": str(e),
                    },
                }

    # Final fallback after all attempts
    if content:
        extracted = extract_answer(content)
        return {
            "answer": f"<answer>{extracted}</answer>",
            "traces": {
                "method": "structured_with_extraction_and_retry",
                "attempts": max_attempts,
                "raw_response": content,
                "extracted_answer": extracted,
                "error": last_error,
            },
        }

    return {
        "answer": "<answer></answer>",
        "traces": {
            "method": "structured_with_extraction_and_retry",
            "attempts": max_attempts,
            "error": last_error,
        },
    }

"""Best-of-N Sudoku solver with self-verification and robust extraction."""

import re
import asyncio
from collections import defaultdict
from harness_evolve.llm import llm_acall

SYSTEM_PROMPT = (
    "You are solving a 4x4 Mini Sudoku puzzle. Follow these steps:\n"
    "1. Analyze the given clues and note missing numbers for each row, column, and 2x2 subgrid.\n"
    "2. Fill in cells step-by-step, ensuring no row, column, or subgrid contains duplicates.\n"
    "3. Before outputting, explicitly verify that each row, column, and subgrid contains exactly the numbers 1-4.\n"
    "4. Wrap your final, verified 4x4 grid in <answer> tags. Output nothing else.\n"
    "The final answer must be in this exact format: <answer>row1\nrow2\nrow3\nrow4</answer>\n"
    "Each row has 4 numbers separated by spaces."
)

MAX_ATTEMPTS = 4

FALLBACK_GRID_RE = re.compile(
    r'^(\d\s+\d\s+\d\s+\d\n){3}\d\s+\d\s+\d\s+\d$',
    re.MULTILINE
)

ANSWER_TAG_RE = re.compile(r'<answer>\s*(.*?)\s*</answer>', re.DOTALL)


def parse_grid(text):
    """Parse a 4x4 grid from text, returning a list of 4 lists of ints or None."""
    lines = text.strip().split('\n')
    lines = [l.strip() for l in lines if l.strip()]
    if len(lines) != 4:
        return None
    grid = []
    for line in lines:
        parts = line.split()
        if len(parts) != 4:
            return None
        row = []
        for p in parts:
            try:
                row.append(int(p))
            except ValueError:
                return None
        if any(v < 1 or v > 4 for v in row):
            return None
        grid.append(row)
    return grid


def verify_sudoku(grid):
    """Check that a 4x4 grid satisfies all Sudoku constraints. Returns True/False."""
    if grid is None or len(grid) != 4:
        return False
    for r in range(4):
        if sorted(grid[r]) != [1, 2, 3, 4]:
            return False
    for c in range(4):
        col = [grid[r][c] for r in range(4)]
        if sorted(col) != [1, 2, 3, 4]:
            return False
    for br in range(2):
        for bc in range(2):
            sub = []
            for r in range(br * 2, br * 2 + 2):
                for c in range(bc * 2, bc * 2 + 2):
                    sub.append(grid[r][c])
            if sorted(sub) != [1, 2, 3, 4]:
                return False
    return True


def score_partial_grid(grid, question):
    """Compute a partial match score for a grid against the puzzle clues."""
    # Extract given clues from the question
    grid_pattern = re.compile(r'(\d|_)\s+(\d|_)\s+(\d|_)\s+(\d|_)', re.MULTILINE)
    matches = grid_pattern.findall(question)
    if not matches:
        return 0.0
    total = 0
    correct = 0
    for m in matches:
        for symbol in m:
            if symbol == '_':
                continue
            total += 1
    if total == 0:
        return 0.0
    # Compare each cell
    for r in range(4):
        if r >= len(grid):
            break
        for c in range(4):
            if c >= len(grid[r]):
                break
            # Find the corresponding clue position
            pass
    # Simpler approach: check how many given clues match
    # Extract rows from question
    clue_lines = re.findall(r'(\d|_)\s+(\d|_)\s+(\d|_)\s+(\d|_)', question)
    if len(clue_lines) != 4:
        # Fallback: count matching non-underscore clues
        pass
    matches = 0
    total_clues = 0
    idx = 0
    for symbol in clue_lines[0]:
        if symbol != '_':
            total_clues += 1
            if grid[0][idx] == int(symbol):
                matches += 1
        idx += 1
    idx = 0
    for symbol in clue_lines[1]:
        if symbol != '_':
            total_clues += 1
            if grid[1][idx] == int(symbol):
                matches += 1
        idx += 1
    idx = 0
    for symbol in clue_lines[2]:
        if symbol != '_':
            total_clues += 1
            if grid[2][idx] == int(symbol):
                matches += 1
        idx += 1
    idx = 0
    for symbol in clue_lines[3]:
        if symbol != '_':
            total_clues += 1
            if grid[3][idx] == int(symbol):
                matches += 1
        idx += 1
    return (matches / total_clues) if total_clues > 0 else 0.0


def extract_grid(content):
    """Try multiple strategies to extract a 4x4 grid from the model's response."""
    # Strategy 1: Strict <answer> tag
    m = ANSWER_TAG_RE.search(content)
    if m:
        grid = parse_grid(m.group(1))
        if grid is not None:
            return grid, "answer_tag"

    # Strategy 2: Fallback regex - find any 4x4 grid pattern
    fm = FALLBACK_GRID_RE.search(content)
    if fm:
        grid = parse_grid(fm.group(1))
        if grid is not None:
            return grid, "fallback_regex"

    # Strategy 3: Search for a block of 4 lines each containing 4 digits
    block_re = re.compile(r'((?:\d\s+){3}\d\n){3}(?:\d\s+){3}\d')
    bm = block_re.search(content)
    if bm:
        grid = parse_grid(bm.group(1))
        if grid is not None:
            return grid, "multiline_block"

    # Strategy 4: Extract last 4 lines that look like grid rows
    lines = content.strip().split('\n')
    grid_lines = []
    for line in reversed(lines):
        parts = line.strip().split()
        if len(parts) == 4 and all(p.isdigit() for p in parts):
            grid_lines.append(line.strip())
            if len(grid_lines) == 4:
                break
    grid_lines.reverse()
    if len(grid_lines) == 4:
        grid = parse_grid('\n'.join(grid_lines))
        if grid is not None:
            return grid, "last_lines"

    return None, None


def grid_to_string(grid):
    """Convert a grid (list of lists) to the expected output format."""
    return '\n'.join(' '.join(str(v) for v in row) for row in grid)


async def solve(model, question, **kwargs):
    """Best-of-N solver with self-verification and robust extraction."""
    traces = {"method": "best_of_n_self_verify", "attempts": []}
    best_grid = None
    best_score = -1.0
    best_extraction_method = None

    for attempt in range(1, MAX_ATTEMPTS + 1):
        # LLM call
        content = await llm_acall(
            model=model,
            messages=[
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": question},
            ],
            max_tokens=32768,
            temperature=0.6,
            thinking=kwargs.get("thinking"),
        )

        # Extract grid
        grid, extraction_method = extract_grid(content)
        verification_result = None

        if grid is not None:
            verification_result = verify_sudoku(grid)

        # Score (partial) for logging
        partial_score = score_partial_grid(grid, question) if grid is not None else 0.0

        attempt_trace = {
            "attempt": attempt,
            "content_length": len(content),
            "extraction_method": extraction_method,
            "verification_passed": verification_result if verification_result is not None else "N/A (no grid extracted)",
            "partial_score": partial_score,
            "grid": grid,
        }
        traces["attempts"].append(attempt_trace)

        # Check if this is a valid solution
        if grid is not None and verification_result:
            # Valid solution found — return immediately
            traces["selected_attempt"] = attempt
            final_answer = f"<answer>{grid_to_string(grid)}</answer>"
            return {"answer": final_answer, "traces": traces}

        # Track best partial score so far
        if grid is not None and partial_score > best_score:
            best_score = partial_score
            best_grid = grid
            best_extraction_method = extraction_method

    # If no valid solution found, return the best partial attempt (or None)
    if best_grid is not None:
        traces["selected_attempt"] = "best_partial"
        traces["best_partial_score"] = best_score
        final_answer = f"<answer>{grid_to_string(best_grid)}</answer>"
    else:
        traces["selected_attempt"] = "none_valid"
        # Fall back to returning the raw content with answer tags wrapping the best we can
        # Try to find any grid-like content
        last_content = traces["attempts"][-1]["content"] if traces["attempts"] else ""
        final_answer = f"<answer>{last_content.strip()}</answer>"

    return {"answer": final_answer, "traces": traces}

"""Improved palindrome partitioning harness with structured output, extraction, and retry logic."""

import re
import json
from typing import Any

from harness_evolve.llm import llm_acall

SYSTEM_PROMPT = (
    "You are solving a palindrome partitioning problem. Given a string, partition it into substrings "
    "such that each substring is a palindrome.\n\n"
    "Return your answer as a JSON list of lists of strings. For example: [[\"a\",\"a\",\"b\"],[\"aa\",\"b\"]]\n\n"
    "Rules:\n"
    "- Each inner list is one valid partition.\n"
    "- Each string in the partition must be a palindrome.\n"
    "- The concatenation of strings in each partition must equal the original string.\n"
    "- Output ONLY the JSON list inside <answer> tags. Do NOT write explanations or code outside the tags.\n"
    "- Example format: <answer>[[\"aab\",\"a\"],[\"aa\",\"b\"]]</answer>\n"
)

RETRY_PROMPT = (
    "Your previous output had parsing issues. Please output ONLY the JSON list of palindrome partitions "
    "inside <answer> tags. Format: <answer>[[\"p1\",\"p2\"],[\"q1\",\"q2\"]]</answer>\n"
    "Do not include any explanation, code, or other text. Only the JSON array."
)


def is_palindrome(s: str) -> bool:
    """Check if a string is a palindrome."""
    return s == s[::-1]


def validate_partition(partition: list, original: str) -> bool:
    """Validate that a partition is correct: all parts are palindromes and concatenate to original."""
    if not isinstance(partition, list):
        return False
    joined = "".join(partition)
    if joined != original:
        return False
    return all(isinstance(part, str) and is_palindrome(part) for part in partition)


def extract_answer(content: str) -> str | None:
    """Extract content between the first <answer>...</answer> tags."""
    match = re.search(r'<answer>\s*(.*?)\s*</answer>', content, re.DOTALL)
    if match:
        return match.group(1).strip()
    return None


def parse_partitions(answer_text: str) -> list[list[str]] | None:
    """Parse the answer text into a list of palindrome partitions (list of lists of strings)."""
    if not answer_text:
        return None
    try:
        parsed = json.loads(answer_text)
    except json.JSONDecodeError:
        return None

    # Handle nested list of lists
    if isinstance(parsed, list) and len(parsed) > 0:
        # The expected format is a list of partitions, each partition is a list of strings
        if isinstance(parsed[0], list):
            return parsed
        # If it's a flat list of strings, wrap it as a single partition
        elif isinstance(parsed[0], str):
            return [parsed]
    return None


async def solve(model, question, **kwargs) -> dict:
    """Solve palindrome partitioning with structured output, extraction, and retry logic."""
    max_retries = 2
    last_content = ""

    for attempt in range(max_retries + 1):
        try:
            if attempt == 0:
                messages = [
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": question},
                ]
            else:
                # Retry with stricter prompt, appending to conversation
                messages = [
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": question},
                    {"role": "assistant", "content": last_content},
                    {"role": "user", "content": RETRY_PROMPT},
                ]

            content = await llm_acall(
                model=model,
                messages=messages,
                max_tokens=2048,
                temperature=0.6,
                thinking=kwargs.get("thinking"),
            )
            last_content = content

            # Extract answer from <answer> tags
            answer_text = extract_answer(content)
            if answer_text is None:
                # No <answer> tags found; try to find JSON-like content
                json_match = re.search(r'\[[\s\S]*\]', content)
                if json_match:
                    answer_text = json_match.group(0)

            if answer_text is not None and len(answer_text) > 0:
                # Try to parse and validate
                partitions = parse_partitions(answer_text)
                if partitions is not None:
                    # Build a clean JSON string for the answer
                    clean_answer = json.dumps(partitions)
                    return {
                        "answer": f"<answer>{clean_answer}</answer>",
                        "traces": {
                            "method": "structured_output_with_retry",
                            "attempts": attempt + 1,
                            "parsed_partitions": partitions,
                            "output_length": len(clean_answer),
                        },
                    }

        except Exception as e:
            # On any exception, continue to retry or fail gracefully
            last_content = last_content or str(e)

    # Final fallback: return best-effort extraction even if unvalidated
    answer_text = extract_answer(last_content) or last_content
    return {
        "answer": f"<answer>{answer_text}</answer>",
        "traces": {
            "method": "structured_output_with_retry_fallback",
            "attempts": max_retries + 1,
            "warning": "parsing or validation failed on all attempts",
        },
    }
